mapper.delete:
delete from STL_SEC_RECON where SEQ_NO  in(
    select SEQ_NO from STL_SEC_RECON_DEAL where RADE_DATE = STR_TO_DATE(#{execDate},'%Y-%m-%d')

)

mapper.sql:
SELECT TO_DATE(T1.JYRQ, 'yyyy-MM-dd') TRADE_DATE, T4.CUSTOMER_ID CUSTOMER_ID, CJBH TRADE_ID, WTBH ENTRUNST_ID, CASE WHEN T1.BZLB = 'RMB' THEN 'CNY' WHEN T1.BZLB = 'HKD' THEN 'HKD' WHEN T1.BZLB = 'USD' THEN 'USD' END CCY, T3.TRADE_MARKET TRADE_MARKET, ZQZH SEC_ACCT_ID, XWBH SEAT_NUMBER, '' SETTLEMEN_TYPE, CJSL TRADE_NUM, CASE WHEN T1.GZZLX !=0 THEN CJJG ELSE NULL END PRICE, YJLX UNIT, CASE WHEN T1.GZZLX !=0 THEN null ELSE CJJG END FULL_PRICE, GZZLX INT_AMT, CJJE TRADE_AMT, NULL TOTAL_TEEAMT, NULL HGDQR, NULL HGDQJE, YHS STAMP_FEE, NULL JSF_AMT, GHF GHF_AMT, NULL ZGF_AMT, NULL SETTLE_FEE, NULL TRADE_FEE, NULL OTHER_FEEAMT, YJ COMMISSION_AMT, WTBH ENTRUST_ID, CASE WHEN CJJE >0 THEN 'T02' ELSE 'T01' END PS, T2.ACCT_NO ACCOUT, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_MARKET_ID END MARKET_ID, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_ID END FINPROD_ID FROM INTERF_DZD T1 LEFT JOIN STL_CAPACCT_INFO T2 ON T2.BUSI_ACCT_NO = T1.ZJZH LEFT JOIN STL_SEC_ACCT_INFO T5 ON T5.SEC_ACCT_ID = T1.ZQZH LEFT JOIN FIN_PRODUCT T3 ON T3.FINPROD_MARKET_ID = CONCAT(T1.ZQDM,CASE WHEN T5.TRADE_PLACE = '03' THEN '.SH' WHEN T5.TRADE_PLACE = '04' then '.SZ' END) LEFT JOIN MST_SEAT T4 ON T4.SEAT_ID = T1.XWBH
EXISTS (SELECT 1 FROM STL_SEC_RECON_CONFIG T6 WHERE T6.JYLB = T1.JYLB AND T6.YWBS = T1.YWBS AND ZYBS IS NULL)
and T4.CUSTOMER_ID IN
#{item.customerId}
and T3.FINPROD_ID not in
#{item.finprodId}
and T1.WTBH not in
#{item.entrustTradeId}
and T1.CJBH not in
#{item.entrustTradeId}
UNION ALL SELECT TO_DATE(T1.JYRQ, 'yyyy-MM-dd') TRADE_DATE, T4.CUSTOMER_ID CUSTOMER_ID, LSH TRADE_ID, WTBH ENTRUNST_ID, CASE WHEN T1.BZ = '0' THEN 'CNY' WHEN T1.BZ = '1' THEN 'HKD' WHEN T1.BZ = '2' THEN 'USD' END CCY, CASE WHEN JYSC = '1' THEN '03' WHEN JYSC = '0' THEN '04' END TRADE_MARKET , ZQZH SEC_ACCT_ID, XWDM SEAT_NUMBER, JSFS SETTLEMEN_TYPE, CJSL TRADE_NUM, CJJJ PRICE, DWYJLX UNIT, CJQJ FULL_PRICE, YJLXZE INT_AMT, QJCJJE TRADE_AMT, FYHJ TOTAL_TEEAMT, HGDQR HGDQR, HGDQJE HGDQJE, YHS STAMP_FEE, JSF JSF_AMT, GHF GHF_AMT, ZGF ZGF_AMT, QSF SETTLE_FEE, JYGF TRADE_FEE, QTF OTHER_FEEAMT, JYJ COMMISSION_AMT, WTBH ENTRUST_ID, CASE WHEN QJCJJE >0 THEN 'T02' ELSE 'T01' END PS, T2.ACCT_NO ACCOUT, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_MARKET_ID END MARKET_ID, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_ID END FINPROD_ID FROM INTERF_ZX_ZJGFLS T1 LEFT JOIN STL_CAPACCT_INFO T2 ON T2.BUSI_ACCT_NO = T1.ZJZH LEFT JOIN FIN_PRODUCT T3 ON T3.FINPROD_MARKET_ID = CONCAT(T1.ZQDM,CASE WHEN T1.JYSC = '0' THEN '.SH' WHEN T1.JYSC = '1' then '.SZ' END) LEFT JOIN MST_SEAT T4 ON T4.SEAT_ID = T1.XWDM WHERE T1.JYSC IN ('0','1') and EXISTS (SELECT 1 FROM STL_SEC_RECON_CONFIG T6 WHERE T6.ZYBS = T1.ZYDM AND ZYBS IS NOT NULL)
AND T4.CUSTOMER_ID IN
#{item.customerId}
and T3.FINPROD_ID not in
#{item.finprodId}
and T1.WTBH not in
#{item.entrustTradeId}
and T1.LSH not in
#{item.entrustTradeId}
